    $sourceInventory=CallModule {param($src,$items) New-WsmInventory $src 1 $items} @($source,@($selectedItem,$otherItem))
    $sourceEntry1=[pscustomobject][ordered]@{SoftwareId=('sw-'+('c'*32));Name='Fixture Runtime';Version='4.2';Publisher='Fixture Vendor';Architecture='x64';Scope='Machine';SID='';RegistryView='Registry64';Location='C:\Fixture\runtime';SourceKind='Registry';Evidence=[pscustomobject]@{RegistryPath='HKLM64\Uninstall\runtime';NaturalKey='fixture-runtime'};ObservedUtc=(Get-Date).ToUniversalTime().ToString('o');CaptureStatus='Success';ItemIds=@($selectedItem.ItemId,$otherItem.ItemId);AccountContext='System'}
    $sourceEntry2=[pscustomobject][ordered]@{SoftwareId=('sw-'+('d'*32));Name='Unselected Provider';Version='3.0';Publisher='Fixture Vendor';Architecture='x64';Scope='Machine';SID='';RegistryView='Registry64';Location='C:\Fixture\unselected';SourceKind='Registry';Evidence=[pscustomobject]@{RegistryPath='HKLM64\Uninstall\unselected';NaturalKey='fixture-unselected'};ObservedUtc=(Get-Date).ToUniversalTime().ToString('o');CaptureStatus='Success';ItemIds=@($otherItem.ItemId);AccountContext='System'}
    function New-SoftwareFixture($Inventory,[object[]]$Entries){$software=[pscustomobject][ordered]@{SchemaVersion=1;ToolVersion='0.4.0';Kind='SoftwareCatalog';Source=[pscustomobject][ordered]@{HostId=$Inventory.Source.HostId;Fingerprint=$Inventory.Source.Fingerprint;Name=$Inventory.Source.Name;InventoryRevision=[int]$Inventory.Revision;InventoryProjectionHash=(CallModule {param($i) Get-WsmSoftwareInventoryProjectionHash $i} @($Inventory))};CaptureContext=[pscustomobject][ordered]@{CapturedUtc=(Get-Date).ToUniversalTime().ToString('o');CaptureIdentity='fixture';AccountContext='System';CaptureHost='fixture';PowerShellVersion='5.1';RequestedPortableRoots=@()};Entries=$Entries;Coverage=@([pscustomobject][ordered]@{Probe='Uninstall';Scope='Machine';SID='';View='Registry64';Status='Success';EvidenceKind='Registry';Count=$Entries.Count;Budget=[pscustomobject]@{MaxEntries=100};ErrorKind=$null;ItemId='';ObservedUtc=(Get-Date).ToUniversalTime().ToString('o')});PreparationRequirements=@(foreach($entry in $Entries){[pscustomobject]@{PreparationId=('prep-'+([string]$entry.SoftwareId).Substring(3));SoftwareId=$entry.SoftwareId;Status='NeedsOwnerReview';RequiredPhase='PreparationReady';EvidenceStatus=$entry.CaptureStatus;ConsumerItemIds=@($entry.ItemIds);Owner='';Reason='Fixture evidence only'}});CatalogProjectionHash=('0'*64)};$software.CatalogProjectionHash=CallModule {param($s) Get-WsmSoftwareCatalogProjectionHash $s} @($software);CallModule {param($s,$i) Assert-WsmSoftwareCatalog $s -SourceInventory $i | Out-Null} @($software,$Inventory);$software}
