    $targetSnapshotPath=Join-Path $root 'target-snapshot.json';SaveJson $targetInventory $targetSnapshotPath | Out-Null;$targetSnapshotHash=(Get-FileHash -LiteralPath $targetSnapshotPath -Algorithm SHA256).Hash.ToLowerInvariant()

