    $prepEvidence=[pscustomobject][ordered]@{MediaReference='fixture-media';MediaSHA256=('e'*64);VerificationMethod='OwnerVerified';SignatureEvidence='signature-review';VendorOSSupportReference='vendor-support';VendorSupportCheckedUtc=(Get-Date).ToUniversalTime().AddMinutes(-1).ToString('o');LicenseReference='license-review';InstallOrder=1;IsolationEvidenceSHA256=('f'*64);RestartStatus='CompletedAndVerified';SideEffectsReference='isolation-review'}
    $requirement1=[pscustomobject][ordered]@{RequirementId='';Type='Preparation';ProviderSoftwareId=$sourceEntry1.SoftwareId;ProviderItemId='';ExternalId='';ConsumerItemIds=@($selectedItem.ItemId,$otherItem.ItemId);Certainty='Required';RequiredPhase='PreparationReady';ExpectedVersion='4.2';Architecture='x64';Context=[pscustomobject][ordered]@{Provider='Fixture Runtime';Version='4.2';Architecture='x64';ConsumerItemIds=@($selectedItem.ItemId,$otherItem.ItemId);PreparationEvidence=$prepEvidence};Owner='runtime owner';SourceProof=[pscustomobject]@{InventoryHash=$sourceHash;RegistryPathHash=('1'*64);Status='NativeObserved'};Decision='Required';DecisionReason='Required by the selected consumer';DecisionEvidence='dependency review'}
    $requirement2=[pscustomobject][ordered]@{RequirementId='';Type='Preparation';ProviderSoftwareId=$sourceEntry2.SoftwareId;ProviderItemId='';ExternalId='';ConsumerItemIds=@($otherItem.ItemId);Certainty='Required';RequiredPhase='PreparationReady';ExpectedVersion='3.0';Architecture='x64';Context=[pscustomobject][ordered]@{Provider='Unselected Provider';Version='3.0';Architecture='x64';ConsumerItemIds=@($otherItem.ItemId);PreparationEvidence=$prepEvidence};Owner='other owner';SourceProof=[pscustomobject]@{InventoryHash=$sourceHash;RegistryPathHash=('2'*64);Status='NativeObserved'};Decision='Required';DecisionReason='Only needed by the unselected consumer';DecisionEvidence='other dependency review'}
    foreach($requirement in @($requirement1,$requirement2)){$requirement.RequirementId=CallModule {param($r) Get-WsmGeneralHostRequirementId $r} @($requirement)}
    $sourceSoftware=[pscustomobject][ordered]@{SchemaVersion=1;ToolVersion='0.4.0';Kind='SoftwareCatalog';Source=[pscustomobject][ordered]@{HostId=$source.HostId;Fingerprint=$source.Fingerprint;Name=$source.Name;InventoryRevision=1;InventoryProjectionHash=(CallModule {param($i) Get-WsmSoftwareInventoryProjectionHash $i} @($sourceInventory))};CaptureContext=$sourceInventory.SoftwareCatalog.CaptureContext;Entries=@($sourceEntry1,$sourceEntry2);Coverage=$sourceInventory.SoftwareCatalog.Coverage;PreparationRequirements=$sourceInventory.SoftwareCatalog.PreparationRequirements;CatalogProjectionHash=('0'*64)};$sourceSoftware.CatalogProjectionHash=CallModule {param($s) Get-WsmSoftwareCatalogProjectionHash $s} @($sourceSoftware)
