    $sourceReference=[pscustomobject][ordered]@{Reference='source-inventory.json';SHA256=$sourceHash;CreatedUtc=(Get-Date).ToUniversalTime().ToString('o');InventoryRevision=1}
    $plan | Add-Member NoteProperty Assistive ([pscustomobject][ordered]@{ContractVersion=1;PairId=$pairId;SourceSnapshotHash=$sourceHash;SourcePolicy='SourceCOnly';SourceSelectionsVersion=$sourceSelectionVersion;ApprovedItemIds=@($selectedItem.ItemId,$otherItem.ItemId);MaterialReferences=@();DiscoveryAuthority=[pscustomobject][ordered]@{SourceSnapshotReference=$sourceReference;InventoryRevision=1;SelectionRevision=$sourceSelectionVersion;Dispositions=@([pscustomobject]@{ItemId=$selectedItem.ItemId;Selected=$true;Decision='Include';Reason='reviewed'},[pscustomobject]@{ItemId=$otherItem.ItemId;Selected=$true;Decision='Include';Reason='reviewed'})}}) -Force
    CallModule {param($p) Assert-WsmAssistiveContract $p MigrationPlan | Out-Null;Assert-WsmGeneralHostSoftwareCatalog $p.GeneralHost.SoftwareCatalog | Out-Null} @($plan)
    $planPath=Join-Path $root 'typed-plan.json';SaveJson $plan $planPath | Out-Null;$planHash=(Get-FileHash -LiteralPath $planPath -Algorithm SHA256).Hash.ToLowerInvariant();$plan=CallModule {param($path,$hash) Read-WsmJson $path $hash} @($planPath,$planHash)
    $manifestPath=Join-Path $root 'fixture-manifest.json';$manifest=[pscustomobject][ordered]@{SchemaVersion=1;ToolVersion='0.4.0';Kind='MigrationManifest';PairId=$pairId;PlanHash=$planHash;Generation=1;Final=$true;Target=$target};SaveJson $manifest $manifestPath | Out-Null;$manifestHash=(Get-FileHash -LiteralPath $manifestPath -Algorithm SHA256).Hash.ToLowerInvariant()
    $package=[pscustomobject][ordered]@{Plan=$plan;Manifest=$manifest;ManifestPath=$manifestPath;ManifestHash=$manifestHash;PlanHash=$planHash;SHA256=$manifestHash}
