    $evidencePath=Join-Path $root 'owner-evidence.bin';$secretSentinel='raw-evidence-secret-sentinel';[IO.File]::WriteAllText($evidencePath,$secretSentinel,(New-Object Text.UTF8Encoding($false)));$evidenceHash=(Get-FileHash -LiteralPath $evidencePath -Algorithm SHA256).Hash.ToLowerInvariant()
    $workspace=Join-Path $root 'target-workspace';[void][IO.Directory]::CreateDirectory($workspace)
    $fixtureIdentity=[pscustomobject]@{HostId=$target.HostId;Fingerprint=$target.Fingerprint;Name=$target.Name;OS=$target.OS;Version=$target.Version;IsServer=$true;Administrator=$true;Is64Bit=$true}
    CallModule {param($pkg,$packagePath,$packageHash,$identity) $script:targetPreparationPackage=$pkg;$script:targetPreparationManifestPath=$packagePath;$script:targetPreparationManifestHash=$packageHash;$script:targetPreparationIdentity=$identity;function script:Test-WsmMigrationPackage {param([string]$ManifestPath,[string]$ExpectedHash) if([IO.Path]::GetFullPath($ManifestPath) -ine [IO.Path]::GetFullPath($script:targetPreparationManifestPath) -or $ExpectedHash -ine $script:targetPreparationManifestHash){throw 'Isolated fixture package validator received an unexpected manifest binding.'};$script:targetPreparationPackage};function script:Get-WsmMachineIdentity {$script:targetPreparationIdentity};function script:Get-WsmAssistiveCurrentSoftwareCatalog($Snapshot){$Snapshot.SoftwareCatalog}} @($package,$manifestPath,$manifestHash,$fixtureIdentity)
    $previewArgs=@{ManifestPath=$manifestPath;ExpectedHash=$manifestHash;AssistiveDecisionReceiptPath=$receiptPath;AssistiveDecisionReceiptHash=$receiptHash;AssistiveTargetSnapshotPath=$targetSnapshotPath}
