    Check ($preview.Rows[0].ExpectedVersion -ceq '5.0' -and $preview.Rows[0].ConsumerItemIds -contains $otherItem.ItemId -and $preview.Rows[0].ContextHash -match '^[a-f0-9]{64}$') 'Preview lost chosen target version, shared source consumer obligations, or safe context hash.'
