    $freshArgs=@{ManifestPath=$manifestPath;ExpectedHash=$manifestHash;AssistiveDecisionReceiptPath=$receiptPath;AssistiveDecisionReceiptHash=$receiptHash;AssistiveTargetSnapshotPath=$targetSnapshotPath;RequirementIds=@($preview.Rows[0].RequirementId);Owner='target runtime owner';EvidencePath=$evidencePath;EvidenceHash=$evidenceHash;ObservedUtc=(Get-Date).ToUniversalTime().ToString('o');ExpiresUtc=(Get-Date).ToUniversalTime().AddHours(2).ToString('o');Workspace=$workspace;AckContextReadback=$true}
    $noAck=$freshArgs.Clone();$noAck.AckContextReadback=$false;Reject {Export-WsmAssistivePreparationEvidence @noAck} 'Preparation evidence was written without context-readback acknowledgment.'
    $unknown=$freshArgs.Clone();$unknown.RequirementIds=@(('9'*64));Reject {Export-WsmAssistivePreparationEvidence @unknown} 'Out-of-scope requirement identity was accepted.'
    $duplicate=$freshArgs.Clone();$duplicate.RequirementIds=@($preview.Rows[0].RequirementId,$preview.Rows[0].RequirementId);Reject {Export-WsmAssistivePreparationEvidence @duplicate} 'Duplicate requirement identities were accepted.'
    $unselected=$freshArgs.Clone();$unselected.RequirementIds=@($requirement2.RequirementId);Reject {Export-WsmAssistivePreparationEvidence @unselected} 'A requirement belonging only to an unselected consumer was accepted.'
