    $badReceipt=$freshArgs.Clone();$badReceipt.AssistiveDecisionReceiptHash=('0'*64);Reject {Export-WsmAssistivePreparationEvidence @badReceipt} 'A stale or corrupted target decision receipt was accepted.'
    $missingAck=$freshArgs.Clone();$missingAck.Remove('AckContextReadback');Reject {Export-WsmAssistivePreparationEvidence @missingAck} 'Evidence factory accepted a missing owner acknowledgment switch.'
    $outputOutside=$freshArgs.Clone();$outputOutside.OutputPath=Join-Path $root 'outside-evidence.json';Reject {Export-WsmAssistivePreparationEvidence @outputOutside} 'Evidence factory wrote outside the protected workspace forms directory.'
    $forms=Join-Path (Join-Path $workspace 'assistive') 'forms';[void][IO.Directory]::CreateDirectory($forms);$collisionPath=Join-Path $forms 'already-exists.json';[IO.File]::WriteAllText($collisionPath,'existing');$collision=$freshArgs.Clone();$collision.OutputPath=$collisionPath;Reject {Export-WsmAssistivePreparationEvidence @collision} 'Evidence factory overwrote an existing output file.'
    $written=Export-WsmAssistivePreparationEvidence @freshArgs
    Check ($written.Status -ceq 'EvidenceRecorded' -and $written.ReadinessProof -eq $false -and $written.ProductionVerified -eq $false -and $written.ReceiptCount -eq 1) 'Public evidence factory returned an overstated gate result or wrong receipt count.'
    Check ((Get-FileHash -LiteralPath $written.Path -Algorithm SHA256).Hash.ToLowerInvariant() -ceq $written.SHA256 -and $written.SHA256 -cne $evidenceHash) 'Generated file hash was not the exact physical bytes hash or was confused with evidence hash.'
    $evidenceSet=CallModule {param($path,$hash) Read-WsmTrustedJson $path $hash} @($written.Path,$written.SHA256)
    Check ($evidenceSet.Kind -ceq 'GeneralHostEvidenceSet' -and $evidenceSet.PairId -ceq $pairId -and $evidenceSet.Receipts.Count -eq 1 -and $evidenceSet.Receipts[0].EvidencePathHash -ceq $evidenceHash -and $evidenceSet.Receipts[0].RequirementProjectionHash -match '^[a-f0-9]{64}$' -and $evidenceSet.Receipts[0].RequirementProjectionHash -cne $evidenceHash) 'Generated receipt confused source evidence bytes with its semantic requirement projection.'
    Check (-not [IO.File]::ReadAllText($written.Path).Contains($secretSentinel)) 'Generated evidence set copied raw physical evidence content.'
