    $targetPlan=CallModule {param($pkg,$d) Get-WsmAssistiveTargetPlan $pkg $d} @($package,$decision)
    $nativeReceipt=$evidenceSet.Receipts[0]
    CallModule {param($r,$p,$targetFingerprint,$planHash) Assert-WsmGeneralHostReceipt $r $p -TargetFingerprint $targetFingerprint -PlanHash $planHash | Out-Null} @($nativeReceipt,$targetPlan,$target.Fingerprint,$planHash)
    Check ($nativeReceipt.Context.AssistiveTargetBinding.DecisionReceiptHash -ceq $receiptHash -and $nativeReceipt.Context.AssistiveTargetBinding.TargetSnapshotHash -ceq $targetSnapshotHash -and $nativeReceipt.Context.AssistiveTargetBinding.ComparisonHash -ceq $receipt.ComparisonHash) 'Generated phase receipt did not preserve all fresh target decision bindings.'

    $registry=CallModule {param($path) Get-WsmAssistiveResourceRegistry $path} @($workspace)
