    function New-TamperedReceiptFile($Original,[string]$Field,[string]$Value,[string]$Name){$copy=CallModule {param($r) ConvertFrom-WsmJson ($r|ConvertTo-Json -Depth 100 -Compress)} @($Original);$copy.Comparison.Rows[0].$Field=$Value;$copy.ComparisonHash=Get-HashTextModule $copy.Comparison;$body=[ordered]@{};foreach($property in $copy.PSObject.Properties){if($property.Name -cne 'SHA256'){$body[$property.Name]=$property.Value}};$copy.SHA256=CallModule {param($v) Get-WsmHashText ($v|ConvertTo-Json -Depth 20 -Compress)} @($body);$path=Join-Path $root $Name;SaveJson $copy $path | Out-Null;[pscustomobject]@{Path=$path;Hash=(Get-FileHash -LiteralPath $path -Algorithm SHA256).Hash.ToLowerInvariant()}}
